-- Postgres structure matching the models as of migration 0002 (no data). Generated by sqlalchemy; do not edit.
CREATE TABLE cases (
	id SERIAL NOT NULL, 
	canonical_title VARCHAR(500) NOT NULL, 
	slug VARCHAR(500) NOT NULL, 
	case_uid VARCHAR(20), 
	status VARCHAR(50) NOT NULL, 
	language VARCHAR(20) NOT NULL, 
