	likely_derivative_of INTEGER, 
	creator_source_family VARCHAR(300), 
	duplicate_group VARCHAR(200), 
	relevance_score FLOAT, 
	novel_information_ratio FLOAT, 
	value_score FLOAT, 
	extraction_cache_key VARCHAR(80), 
	processed_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);
CREATE TABLE voice_performances (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	story_version_id INTEGER NOT NULL, 
	language VARCHAR(20) NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	performance_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	generation_model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(story_version_id) REFERENCES story_versions (id)
);
CREATE TABLE audio_plans (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	plan_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	generation_provider VARCHAR(50), 
	generation_model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id)
);
CREATE TABLE chapter_plans (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	languages_json TEXT NOT NULL, 
	plan_json TEXT NOT NULL, 
	audit_json TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id)
);
CREATE TABLE epistemic_contract_sets (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	story_version_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	coverage_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_epistemic_contract_set UNIQUE (case_id, story_version_id, version), 
	CONSTRAINT ck_epistemic_contract_set_status CHECK (status IN ('draft', 'in_review', 'approved', 'invalid')), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id), 
	FOREIGN KEY(story_version_id) REFERENCES story_versions (id)
);
CREATE TABLE host_plans (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	plan_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	generation_model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id)
);
CREATE TABLE narrative_insights (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	video_source_id INTEGER, 
	insight_type VARCHAR(60) NOT NULL, 
	text_original TEXT, 
	canonical_text_en TEXT NOT NULL, 
	segment_ids_json TEXT NOT NULL, 
	language VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(video_source_id) REFERENCES video_sources (id)
);
CREATE TABLE platform_variants (
	id SERIAL NOT NULL, 
	concept_id INTEGER NOT NULL, 
	script_id INTEGER, 
	platform VARCHAR(40) NOT NULL, 
	language VARCHAR(10) NOT NULL, 
	hook TEXT NOT NULL, 
	caption TEXT NOT NULL, 
	description TEXT NOT NULL, 
	cta TEXT NOT NULL, 
	end_card TEXT NOT NULL, 
	subtitle_layout_json TEXT NOT NULL, 
	cover_frame_json TEXT NOT NULL, 
	duration FLOAT, 
	destination_json TEXT NOT NULL, 
	disclosure_flags_json TEXT NOT NULL, 
	rights_flags_json TEXT NOT NULL, 
	policy_flags_json TEXT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(concept_id) REFERENCES short_form_concepts (id), 
	FOREIGN KEY(script_id) REFERENCES short_form_scripts (id)
);
CREATE TABLE research_results (
	id SERIAL NOT NULL, 
	research_query_id INTEGER, 
	url TEXT NOT NULL, 
	canonical_url VARCHAR(1000), 
	final_url TEXT, 
	title VARCHAR(1000), 
	snippet TEXT, 
	rank INTEGER, 
	provider VARCHAR(50) NOT NULL, 
	model VARCHAR(200), 
	result_language VARCHAR(20), 
	relevance_score FLOAT, 
	credibility_score FLOAT, 
	novelty_score FLOAT, 
	fetch_status VARCHAR(30), 
	accepted BOOLEAN NOT NULL, 
	rejection_reason VARCHAR(60), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(research_query_id) REFERENCES research_queries (id)
);
CREATE TABLE reveal_graphs (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	validation_json TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_reveal_graph_version UNIQUE (case_id, blueprint_id, version), 
	CONSTRAINT ck_reveal_graph_status CHECK (status IN ('draft', 'validated', 'invalid')), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id)
);
CREATE TABLE transcript_claims (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	video_source_id INTEGER NOT NULL, 
	segment_ids_json TEXT NOT NULL, 
	original_language VARCHAR(20) NOT NULL, 
	original_claim TEXT, 
	canonical_claim_en TEXT NOT NULL, 
	claim_type VARCHAR(60) NOT NULL, 
	confidence FLOAT NOT NULL, 
	certainty VARCHAR(40) NOT NULL, 
	speaker VARCHAR(300), 
	quote_classification VARCHAR(40), 
	timestamp_start FLOAT, 
	timestamp_end FLOAT, 
	verification_status VARCHAR(40) NOT NULL, 
	supporting_source_ids_json TEXT NOT NULL, 
	cluster_id INTEGER, 
	promoted_fact_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(video_source_id) REFERENCES video_sources (id), 
	FOREIGN KEY(cluster_id) REFERENCES claim_clusters (id), 
	FOREIGN KEY(promoted_fact_id) REFERENCES facts (id)
);
CREATE TABLE transcript_segments (
	id SERIAL NOT NULL, 
	video_source_id INTEGER NOT NULL, 
	start_seconds FLOAT NOT NULL, 
	end_seconds FLOAT NOT NULL, 
	segment_index INTEGER NOT NULL, 
	text_original TEXT NOT NULL, 
	language VARCHAR(20) NOT NULL, 
	canonical_text_en TEXT, 
	content_hash VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(video_source_id) REFERENCES video_sources (id)
);
CREATE TABLE visual_plans (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	blueprint_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	requirements_json TEXT NOT NULL, 
	plan_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	generation_model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(blueprint_id) REFERENCES editorial_blueprints (id)
);
CREATE TABLE epistemic_claims (
	id SERIAL NOT NULL, 
	contract_set_id INTEGER NOT NULL, 
	claim_key VARCHAR(120) NOT NULL, 
	claim_text TEXT NOT NULL, 
	source_sentence_text TEXT, 
	span_start INTEGER, 
	span_end INTEGER, 
	beat_id VARCHAR(20) NOT NULL, 
	modality VARCHAR(40) NOT NULL, 
	assertion_role VARCHAR(40) NOT NULL, 
	speaker VARCHAR(300), 
	parent_claim_key VARCHAR(120), 
	source_refs_json TEXT NOT NULL, 
	evidence_refs_json TEXT NOT NULL, 
	review_status VARCHAR(20) NOT NULL, 
	reviewer_notes TEXT, 
	origin VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_epistemic_claim_key UNIQUE (contract_set_id, claim_key), 
	CONSTRAINT ck_epistemic_claim_modality CHECK (modality IN ('ESTABLISHED', 'BELIEVED_BY_INVESTIGATORS', 'ALLEGED', 'ABSENCE_OF_EVIDENCE', 'DISPUTED')), 
	CONSTRAINT ck_epistemic_claim_review_status CHECK (review_status IN ('proposed', 'approved', 'rejected')), 
	FOREIGN KEY(contract_set_id) REFERENCES epistemic_contract_sets (id)
);
CREATE TABLE host_segments (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	story_version_id INTEGER NOT NULL, 
	host_plan_id INTEGER NOT NULL, 
	language VARCHAR(20) NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	segments_json TEXT NOT NULL, 
	validation_json TEXT NOT NULL, 
	generation_model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(story_version_id) REFERENCES story_versions (id), 
	FOREIGN KEY(host_plan_id) REFERENCES host_plans (id)
);
CREATE TABLE research_source_links (
	id SERIAL NOT NULL, 
	research_result_id INTEGER NOT NULL, 
	source_id INTEGER NOT NULL, 
	relationship VARCHAR(40) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(research_result_id) REFERENCES research_results (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);
CREATE TABLE reveal_nodes (
	id SERIAL NOT NULL, 
	graph_id INTEGER NOT NULL, 
	node_key VARCHAR(120) NOT NULL, 
	label VARCHAR(500) NOT NULL, 
	category VARCHAR(60) NOT NULL, 
	first_revealed_beat_id VARCHAR(20) NOT NULL, 
	first_revealed_order INTEGER NOT NULL, 
	first_revealed_at_seconds FLOAT, 
	description TEXT, 
	metadata_json TEXT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_reveal_node_key UNIQUE (graph_id, node_key), 
	FOREIGN KEY(graph_id) REFERENCES reveal_graphs (id)
);
CREATE TABLE short_form_metrics (
	id SERIAL NOT NULL, 
	variant_id INTEGER, 
	platform VARCHAR(40) NOT NULL, 
	metric_date VARCHAR(40), 
	views INTEGER NOT NULL, 
	unique_viewers INTEGER, 
	average_watch_time FLOAT, 
	completion_rate FLOAT, 
	rewatches INTEGER, 
	likes INTEGER NOT NULL, 
	comments INTEGER NOT NULL, 
	shares INTEGER NOT NULL, 
	saves INTEGER NOT NULL, 
	profile_visits INTEGER, 
	link_clicks INTEGER, 
	youtube_clicks INTEGER, 
	new_subscribers INTEGER, 
	destination_clicks INTEGER, 
	youtube_episode_visits INTEGER, 
	estimated_conversion_rate FLOAT, 
	attribution_status VARCHAR(40) NOT NULL, 
	raw_json TEXT NOT NULL, 
	detail_json TEXT NOT NULL, 
	model VARCHAR(200), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(variant_id) REFERENCES platform_variants (id)
);
CREATE TABLE reveal_asset_links (
	id SERIAL NOT NULL, 
	graph_id INTEGER NOT NULL, 
	node_id INTEGER NOT NULL, 
	visual_asset_id INTEGER, 
	original_media_segment_id INTEGER, 
	asset_kind VARCHAR(20) NOT NULL, 
	note TEXT, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_reveal_asset_target CHECK (visual_asset_id IS NOT NULL OR original_media_segment_id IS NOT NULL), 
	CONSTRAINT ck_reveal_asset_kind CHECK (asset_kind IN ('visual', 'audio')), 
	FOREIGN KEY(graph_id) REFERENCES reveal_graphs (id), 
	FOREIGN KEY(node_id) REFERENCES reveal_nodes (id), 
	FOREIGN KEY(visual_asset_id) REFERENCES visual_assets (id), 
	FOREIGN KEY(original_media_segment_id) REFERENCES original_media_segments (id)
);
CREATE TABLE reveal_edges (
	id SERIAL NOT NULL, 
	graph_id INTEGER NOT NULL, 
	prerequisite_node_id INTEGER NOT NULL, 
	dependent_node_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_reveal_edge UNIQUE (graph_id, prerequisite_node_id, dependent_node_id), 
	CONSTRAINT ck_reveal_no_self_edge CHECK (prerequisite_node_id != dependent_node_id), 
	FOREIGN KEY(graph_id) REFERENCES reveal_graphs (id), 
	FOREIGN KEY(prerequisite_node_id) REFERENCES reveal_nodes (id), 
	FOREIGN KEY(dependent_node_id) REFERENCES reveal_nodes (id)
);
CREATE TABLE reveal_exposures (
	id SERIAL NOT NULL, 
	graph_id INTEGER NOT NULL, 
	beat_id VARCHAR(20) NOT NULL, 
	node_id INTEGER NOT NULL, 
	exposure_type VARCHAR(20) NOT NULL, 
	source_field VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_reveal_exposure UNIQUE (graph_id, beat_id, node_id), 
	CONSTRAINT ck_reveal_exposure_type CHECK (exposure_type IN ('exposed', 'withheld')), 
	FOREIGN KEY(graph_id) REFERENCES reveal_graphs (id), 
	FOREIGN KEY(node_id) REFERENCES reveal_nodes (id)
);
